fn project_terminal_snapshot(value: serde_json::Value) -> serde_json::Value {
    let mut result = select_fields(
        &value,
        &[
            "coreGeneration",
            "exists",
            "generation",
            "launchRequestId",
            "phase",
            "cols",
            "rows",
            "exitCode",
            "throughSeq",
            "firstAvailableSeq",
            "gap",
            "inputSequence",
            "issue",
            "cleanupComplete",
        ],
    );
    result["target"] = select_fields(&value["target"], &["boardId", "nodeId"]);
    for (name, fields) in [
        ("chunks", &["seq", "bytesBase64"][..]),
        ("inputs", &["sequence", "inputId", "status"][..]),
    ] {
        result[name] = serde_json::Value::Array(
            value[name]
                .as_array()
                .map(|items| {
                    items
                        .iter()
                        .map(|item| select_fields(item, fields))
                        .collect()
                })
                .unwrap_or_default(),
        );
    }
    result
}

fn select_fields(value: &serde_json::Value, fields: &[&str]) -> serde_json::Value {
    let mut object = serde_json::Map::new();
    for field in fields {
        if let Some(value) = value.get(field) {
            object.insert((*field).into(), value.clone());
        }
    }
    serde_json::Value::Object(object)
}
fn project_mcp_config(value: serde_json::Value) -> serde_json::Value {
    let mut projected = select_fields(
        &value,
        &[
            "path",
            "exists",
            "configDigest",
            "publicConfigJson",
            "fileIssue",
            "permissionIssue",
        ],
    );
    projected["servers"] = serde_json::json!(
        value["servers"]
            .as_array()
            .map(|servers| servers
                .iter()
                .map(|server| select_fields(
                    server,
                    &[
                        "serverId",
                        "name",
                        "transport",
                        "endpoint",
                        "enabled",
                        "assignedAgentIds",
                        "source",
                        "riskLevel",
                        "riskAcknowledged",
                        "definitionJson",
                        "configurationIssues"
                    ]
                ))
                .collect::<Vec<_>>())
            .unwrap_or_default()
    );
    projected
}

fn filter_actions(value: &mut serde_json::Value, task_updates: bool) {
    match value {
        serde_json::Value::Object(object) => {
            if object.contains_key("availableActions") {
                let actions = if task_updates
                    && object
                        .get("taskId")
                        .is_some_and(serde_json::Value::is_string)
                {
                    object["availableActions"]
                        .as_array()
                        .map(|actions| {
                            actions
                                .iter()
                                .filter(|action| action.as_str() == Some("update"))
                                .cloned()
                                .collect::<Vec<_>>()
                        })
                        .unwrap_or_default()
                } else {
                    Vec::new()
                };
                object.insert("availableActions".into(), serde_json::json!(actions));
            }
            for value in object.values_mut() {
                filter_actions(value, task_updates);
            }
        }
        serde_json::Value::Array(array) => {
            for value in array {
                filter_actions(value, task_updates);
            }
        }
        _ => {}
    }
}

#[cfg(test)]
mod tests {
    use super::Operation;
    use serde_json::json;

    // Owns the network projection boundary, not Core's internal MCP model.
    #[test]
    fn public_projection_excludes_mcp_credentials_and_desktop_mutation_actions() {
        let read_view = json!({"readId":"read", "coreGeneration":"generation", "state":"ready",
            "snapshotReference":"signed", "code":null, "futurePath":"private-source", "futureToken":"credential"});
        for operation in [Operation::NativeAgentReadStart, Operation::NativeAgentReadPoll,Operation::NativeChildReadStart, Operation::NativeChildReadPoll] {
            assert_eq!(operation.project(read_view.clone()), json!({"readId":"read","coreGeneration":"generation",
                "state":"ready","snapshotReference":"signed","code":null}));
        }
        let long = "完整中文😀".repeat(8000);
        let source = json!({"state":"bound", "source":{"threadId":"thread","evidenceId":"evidence"},
            "operation":"delegation.resume", "attemptNo":2, "detail":{"delegationId":"child"},
            "task":long,"reason":"  恢复中文😀\n保留空白  ","futurePrivatePath":"private-source"});
        let mut expected_source = source.clone();
        expected_source.as_object_mut().unwrap().remove("futurePrivatePath");
        assert_eq!(Operation::DelegationSource.project(source), expected_source);
        let page = Operation::NativeChildReadPage.project(json!({"snapshotReference":"signed","projectionDigest":"projection",
            "sourceDigest":"source","offset":0,"totalBytes":long.len(),"fragment":long,"nextCursor":null,
            "complete":true,"reportedStatus":"completed","live":false,"futurePrivatePath":"private-source"}));
        assert_eq!(page["fragment"], long);
        assert!(page.get("futurePrivatePath").is_none());
        assert_eq!(Operation::NativeAgentReadPage.project(page.clone()),page);
        assert!(Operation::NativeAgentReadPage.project(json!({"fragment":long,"futurePrivatePath":"private"})).get("futurePrivatePath").is_none());
        assert_eq!(Operation::NativeAgentReadClose.project(json!({"closed":true,"futureSecret":"credential"})),json!({"closed":true}));
        assert_eq!(Operation::NativeChildReadClose.project(json!({"closed":true,"futureSecret":"credential"})), json!({"closed":true}));
        let projected = Operation::Mcp.project(json!({"servers":[{
            "serverId":"fixture", "name":"Example", "enabled":true,
            "transport":"http", "assignedAgentIds":[],
            "headers":{"Authorization":"fixture-secret"},
            "definitionJson":"{\"mcpServers\":{\"Example\":{\"url\":\"********\"}}}", "endpoint":"********",
            "futureCredentialField":"fixture-secret"
        }]}));
        assert_eq!(
            projected,
            json!({"servers":[{"serverId":"fixture", "name":"Example", "enabled":true,
            "transport":"http", "assignedAgentIds":[], "definitionJson":"{\"mcpServers\":{\"Example\":{\"url\":\"********\"}}}", "endpoint":"********"}]})
        );
        assert_eq!(
            Operation::Tasks
                .project(json!({"items":[{"taskId":"task_fixture", "body":"keep content", "availableActions":["update","edit"]}]})),
            json!({"items":[{"taskId":"task_fixture", "body":"keep content", "availableActions":["update"]}]})
        );
        assert!(serde_json::from_value::<Operation>(json!("host.web.rotate")).is_err());
        assert!(
            serde_json::from_value::<Operation>(json!("camp.message.send_user_draft")).is_err()
        );
        let withdraw = serde_json::from_value::<Operation>(json!("camp.messages.withdraw"))
            .expect("User message withdrawal should be admitted by the Web Host");
        assert_eq!(withdraw.method(), "camp.messages.withdraw");
        for (public, internal) in [
            ("delegations.resume", "delegations.resume"),
            ("delegations.list", "delegations.list"),
            ("delegations.get", "delegations.get"),
            ("delegations.source", "delegations.source"),
            ("delegations.history", "delegations.history"),
            ("delegations.read", "delegations.read"),
            ("delegations.settings.get", "delegations.settings.get"),
            ("delegations.settings.update", "delegations.settings.update"),
            ("runtime.interactions.list", "runtime.interactions.list"),
            ("runtime.interactions.get", "runtime.interactions.get"),
            (
                "runtime.interactions.resolve",
                "runtime.interactions.resolve",
            ),
            ("runtime.childReads.start", "runtime.childReads.start"),
            ("runtime.agentReads.start", "runtime.agentReads.start"),
            ("runtime.agentReads.poll", "runtime.agentReads.poll"),
            ("runtime.agentReads.page", "runtime.agentReads.page"),
            ("runtime.agentReads.close", "runtime.agentReads.close"),
            ("runtime.childReads.poll", "runtime.childReads.poll"),
            ("runtime.childReads.page", "runtime.childReads.page"),
            ("runtime.childReads.close", "runtime.childReads.close"),
            ("delegations.composer.get", "delegations.composer.get"),
            ("delegations.conversation.get", "delegations.conversation.get"),
            ("delegations.message.send", "delegations.message.send"),
            ("delegations.takeover", "delegations.takeover"),
            ("delegations.cancel", "delegations.cancel"),
            (
                "delegations.conversation.end",
                "delegations.conversation.end",
            ),
            (
                "delegations.pendingInputs.get",
                "delegations.pendingInputs.get",
            ),
            (
                "delegations.pendingInputs.edit",
                "delegations.pendingInputs.edit",
            ),
            ("delegations.composer.mutate", "delegations.composer.mutate"),
            (
                "delegations.composer.recovery",
                "delegations.composer.recovery",
            ),
            (
                "singleChat.composerDraft.mutate",
                "singleChat.composerDraft.mutate",
            ),
            (
                "singleChat.composerDraft.recovery",
                "singleChat.composerDraft.recovery",
            ),
            ("thread.messages.anchors", "camp.messages.anchors"),
            (
                "thread.messages.anchorPreview",
                "camp.messages.anchorPreview",
            ),
        ] {
            assert_eq!(
                serde_json::from_value::<Operation>(json!(public))
                    .unwrap()
                    .method(),
                internal
            );
        }
        let continuation =
            serde_json::from_value::<Operation>(json!("agentRuns.continue")).unwrap();
        assert_eq!(continuation.method(), "agentRuns.continue");
        // 终端只投影公开字节块及回执，不能扩散将来新增的进程内部字段。
        let terminal = json!({"coreGeneration":"core", "target":{"boardId":"board", "nodeId":"node", "cwd":"private"},
            "exists":true, "generation":"generation", "launchRequestId":"original", "phase":"running", "cols":80, "rows":24,
            "exitCode":null, "throughSeq":1, "firstAvailableSeq":1, "gap":false, "inputSequence":1, "issue":null, "cleanupComplete":false,
            "chunks":[{"seq":1, "bytesBase64":"ABv/", "future":"private"}],
            "inputs":[{"sequence":1, "inputId":"original", "status":"written", "digest":"private", "bytesBase64":"private"}],
            "pid":123, "environment":"private"});
        for name in [
            "canvas.terminals.start",
            "canvas.terminals.snapshot",
            "canvas.terminals.write",
            "canvas.terminals.resize",
            "canvas.terminals.stop",
        ] {
            let operation = serde_json::from_value::<Operation>(json!(name)).unwrap();
            assert_eq!(operation.method(), name);
        }
        let mut expected = terminal.clone();
        expected.as_object_mut().unwrap().remove("pid");
        expected.as_object_mut().unwrap().remove("environment");
        expected["target"] = json!({"boardId":"board", "nodeId":"node"});
        expected["chunks"] = json!([{"seq":1, "bytesBase64":"ABv/"}]);
        expected["inputs"] = json!([{"sequence":1, "inputId":"original", "status":"written"}]);
        assert_eq!(
            Operation::CanvasTerminalStart.project(terminal.clone()),
            expected
        );
        assert_eq!(
            Operation::CanvasTerminalSnapshot.project(terminal),
            expected
        );
        assert_eq!(
            Operation::CanvasTerminalWrite.project(
                json!({"sequence":1, "inputId":"original", "status":"unknown", "digest":"private"})
            ),
            json!({"sequence":1, "inputId":"original", "status":"unknown"})
        );
        assert_eq!(
            Operation::CanvasTerminalResize.project(json!({"resized":true, "pid":123})),
            json!({"resized":true})
        );
        assert_eq!(
            Operation::CanvasTerminalStop.project(json!({"stopping":true, "pid":123})),
            json!({"stopping":true})
        );
    }
}
